#!/usr/bin/env python3
"""Turn kernel/assets/qr_tables.json into kernel/qr_tables.h.

usage: gen-qr-tables.py INPUT.json OUTPUT.h
"""
from pathlib import Path
import json
import sys


def main(argv):
    if len(argv) != 3:
        print(f'usage: {argv[0]} INPUT.json OUTPUT.h', file=sys.stderr)
        return 2
    doc = json.loads(Path(argv[1]).read_text())
    levels = doc['levels']
    max_version = doc['max_version']

    max_align = max(len(v) for v in doc['alignment'].values())
    out = [
        '#pragma once',
        '// Generated by scripts/gen-qr-tables.py from kernel/assets/qr_tables.json.',
        '// QR Model-2 spec tables; never hand-edit. Source data provenance: see the JSON.',
        '',
        '#include "anko/types.h"',
        '',
        'namespace anko::qr::tables {',
        '',
        '// Level order used by every table here.',
        'enum : u8 { kLevelL = 0, kLevelM = 1, kLevelQ = 2, kLevelH = 3, kLevelCount = 4 };',
        f'constexpr u32 kVersionCount = {max_version};',
        '',
        f'constexpr u32 kMaxAlign = {max_align};',
        '',
        'struct EcGroup { u8 blocks; u8 ec_bytes; u8 data_bytes; };',
        'struct EcSpec { u8 group_count; EcGroup groups[2]; };',
        '',
        '// [version-1][level]',
        f'inline constexpr EcSpec kEc[{max_version}][kLevelCount] = {{',
    ]
    for version in range(1, max_version + 1):
        row = []
        for level in levels:
            groups = doc['ec'][str(version)][level]
            parts = ', '.join(f'{{{g["blocks"]}, {g["ec"]}, {g["data"]}}}' for g in groups)
            pad = '' if len(groups) == 2 else ', {0, 0, 0}'
            row.append('{' + str(len(groups)) + ', {' + parts + pad + '}}')
        out.append('    { ' + ', '.join(row) + ' },')
    out += [
        '};',
        '',
        '// Alignment-pattern centres; kAlignCount[v-1] is the real length.',
        f'inline constexpr u8 kAlign[{max_version}][kMaxAlign] = {{',
    ]
    for version in range(1, max_version + 1):
        coords = doc['alignment'].get(str(version), [])
        cells = [str(c) for c in coords] + ['0'] * (max_align - len(coords))
        out.append('    { ' + ', '.join(cells) + ' },')
    out += [
        '};',
        f'inline constexpr u8 kAlignCount[{max_version}] = {{',
        '    ' + ', '.join(str(len(doc['alignment'].get(str(v), []))) for v in range(1, max_version + 1)),
        '};',
        '',
        '// index = (level_code << 3) | mask, level_code: L=1 M=0 Q=3 H=2.',
        'inline constexpr u16 kFormatInfo[32] = {',
        '    ' + ', '.join('0x%04X' % v for v in doc['format_info']),
        '};',
        '',
        '// index = version-1; 0 for versions below 7.',
        f'inline constexpr u32 kVersionInfo[{max_version}] = {{',
    ]
    words = [doc['version_info'].get(str(v), 0) for v in range(1, max_version + 1)]
    for i in range(0, max_version, 8):
        out.append('    ' + ', '.join('0x%06X' % w for w in words[i:i + 8]) + ',')
    out += [
        '};',
        '',
        '} // namespace anko::qr::tables',
        '',
    ]
    Path(argv[2]).write_text('\n'.join(out))
    print(f'wrote {argv[2]}')
    return 0


if __name__ == '__main__':
    raise SystemExit(main(sys.argv))
